import os
import sys
import json
import re
from cli import get_config_dir

VALID_ACTIONS = {
    "Quit",
    "Suspend",
    "Refresh",
    "LoopOverTabs",
    "BackLoopOverTabs",
    "ProcessReplace",
    "ShowHelp",
}

def strip_json_comments(text):
    # Strip // comments and /* */ comments
    lines = []
    for line in text.splitlines():
        line_clean = re.sub(r'//.*$', '', line)
        lines.append(line_clean)
    text_clean = '\n'.join(lines)
    text_clean = re.sub(r'/\*.*?\*/', '', text_clean, flags=re.DOTALL)
    # Strip trailing commas before } or ]
    text_clean = re.sub(r',\s*([}\]])', r'\1', text_clean)
    return text_clean

def parse_simple_toml(text, filepath):
    # Parse TOML file supporting keybindings = { "<Key>" = "Action" }
    # or keybindings dict
    data = {}
    lines = text.splitlines()
    i = 0
    while i < len(lines):
        line = lines[i].strip()
        if not line or line.startswith('#'):
            i += 1
            continue
        if '=' in line:
            parts = line.split('=', 1)
            key = parts[0].strip()
            val = parts[1].strip()
            if val.startswith('{') and val.endswith('}'):
                # Inline table
                inner = val[1:-1].strip()
                kdict = {}
                if inner:
                    # e.g. "<Ctrl-a>" = "Quit" or "<Ctrl-a>": "Quit"
                    for item in re.split(r',\s*', inner):
                        if '=' in item or ':' in item:
                            sep = '=' if '=' in item else ':'
                            k, v = item.split(sep, 1)
                            k = k.strip().strip('"').strip("'")
                            v = v.strip().strip('"').strip("'")
                            if k or v:
                                kdict[k] = v
                data[key] = kdict
            elif val.startswith('{'):
                # Multiline dict
                kdict = {}
                i += 1
                while i < len(lines):
                    l = lines[i].strip()
                    if l.startswith('}'):
                        break
                    if '=' in l or ':' in l:
                        sep = '=' if '=' in l else ':'
                        k, v = l.split(sep, 1)
                        k = k.strip().strip('"').strip("'")
                        v = v.strip().strip('"').strip("'")
                        if k or v:
                            kdict[k] = v
                    i += 1
                data[key] = kdict
            else:
                data[key] = val.strip('"').strip("'")
        else:
            # Syntax error in TOML
            col = len(line)
            raise ValueError(f"TOML parse error at line {i+1}, column {col}\n  |\n{i+1} | {line}\n  | \nexpected `.`, `=`\n in {filepath}")
        i += 1
    return data

def load_config():
    config_dir = get_config_dir()
    filenames = ["config.toml", "config.json", "config.json5"]

    config_file = None
    for fn in filenames:
        fp = os.path.join(config_dir, fn)
        if os.path.exists(fp) and os.path.isfile(fp):
            config_file = fp
            break

    if not config_file:
        return {}

    try:
        with open(config_file, 'r', encoding='utf-8') as f:
            content = f.read()

        if config_file.endswith('.toml'):
            data = parse_simple_toml(content, config_file)
        else:
            clean_content = strip_json_comments(content)
            data = json.loads(clean_content)
    except Exception as e:
        sys.stderr.write(f"serpl error: Something went wrong\nError: \n   0: \x1b[91m{e}\x1b[0m\n")
        sys.exit(1)

    if not isinstance(data, dict):
        sys.stderr.write(f"serpl error: Something went wrong\nError: \n   0: \x1b[91minvalid type: {type(data).__name__}, expected a map\x1b[0m\n")
        sys.exit(1)

    keybindings = data.get("keybindings", {})
    if not isinstance(keybindings, dict):
        sys.stderr.write(f"serpl error: Something went wrong\nError: \n   0: \x1b[91minvalid type: {type(keybindings).__name__}, expected a map\x1b[0m\n")
        sys.exit(1)

    for k, act in keybindings.items():
        if act not in VALID_ACTIONS:
            sys.stderr.write(f"serpl error: Something went wrong\nError: \n   0: \x1b[91mUnknown Action variant: {act}\x1b[0m\n")
            sys.exit(1)

    return data
