import os
import re
import fnmatch

SEARCH_MODES = [
    "[Simple]",
    "[Match Case]",
    "[Match Whole Word]",
    "[Match Case Whole Word]",
    "[Regex]"
]

class LineMatch:
    def __init__(self, line_num, text, matches):
        self.line_num = line_num # 1-based
        self.text = text
        self.matches = matches # list of (start, end) tuples

class FileResult:
    def __init__(self, rel_path, full_path, lines):
        self.rel_path = rel_path
        self.full_path = full_path
        self.lines = lines # List[LineMatch]
        self.match_count = sum(len(l.matches) for l in lines)

def load_gitignore(root_dir):
    patterns = []
    for dirpath, dirnames, filenames in os.walk(root_dir):
        # Do not enter hidden dirs
        dirnames[:] = [d for d in dirnames if not d.startswith('.')]
        if '.gitignore' in filenames:
            gi_path = os.path.join(dirpath, '.gitignore')
            try:
                with open(gi_path, 'r', encoding='utf-8', errors='ignore') as f:
                    for line in f:
                        line = line.strip()
                        if line and not line.startswith('#'):
                            rel_dir = os.path.relpath(dirpath, root_dir)
                            if rel_dir == '.':
                                prefix = ""
                            else:
                                prefix = rel_dir + "/"
                            patterns.append((prefix, line))
            except Exception:
                pass
    return patterns

def is_ignored(rel_path, is_dir, gitignore_patterns):
    parts = rel_path.split(os.sep)
    for part in parts:
        if part.startswith('.'):
            return True

    for prefix, pattern in gitignore_patterns:
        target = rel_path
        if prefix and rel_path.startswith(prefix):
            target = rel_path[len(prefix):]
        elif prefix:
            continue

        pattern_clean = pattern.rstrip('/')
        if fnmatch.fnmatch(target, pattern_clean) or fnmatch.fnmatch(os.path.basename(target), pattern_clean):
            return True
    return False

def get_compiled_regex(pattern_str, mode_idx):
    if not pattern_str:
        return None
    try:
        if mode_idx == 0: # [Simple]
            return re.compile(re.escape(pattern_str), re.IGNORECASE)
        elif mode_idx == 1: # [Match Case]
            return re.compile(re.escape(pattern_str))
        elif mode_idx == 2: # [Match Whole Word]
            return re.compile(r'\b' + re.escape(pattern_str) + r'\b', re.IGNORECASE)
        elif mode_idx == 3: # [Match Case Whole Word]
            return re.compile(r'\b' + re.escape(pattern_str) + r'\b')
        elif mode_idx == 4: # [Regex]
            return re.compile(pattern_str)
    except Exception:
        return None
    return None

def is_binary_file(full_path):
    try:
        with open(full_path, 'rb') as f:
            chunk = f.read(1024)
            if b'\x00' in chunk:
                return True
    except Exception:
        return True
    return False

def search_project(project_root, pattern_str, mode_idx):
    regex = get_compiled_regex(pattern_str, mode_idx)
    if not regex:
        return []

    gitignore_patterns = load_gitignore(project_root)

    root_files = []
    sub_files = []

    for dirpath, dirnames, filenames in os.walk(project_root):
        # Exclude hidden directories
        dirnames[:] = [d for d in dirnames if not d.startswith('.')]

        rel_dir = os.path.relpath(dirpath, project_root)
        if rel_dir == '.':
            rel_dir = ""

        for fname in sorted(filenames):
            if fname.startswith('.'):
                continue
            rel_path = os.path.join(rel_dir, fname) if rel_dir else fname

            if is_ignored(rel_path, False, gitignore_patterns):
                continue

            full_path = os.path.join(project_root, rel_path)
            if is_binary_file(full_path):
                continue

            if not rel_dir:
                root_files.append((fname, rel_path, full_path))
            else:
                sub_files.append((rel_path, rel_path, full_path))

    root_files.sort(key=lambda x: x[0])
    sub_files.sort(key=lambda x: x[0])
    all_files = [x[1:] for x in root_files] + [x[1:] for x in sub_files]

    results = []
    for rel_path, full_path in all_files:
        try:
            with open(full_path, 'r', encoding='utf-8', errors='ignore') as f:
                content_lines = f.readlines()
        except Exception:
            continue

        file_matches = []
